    /** Kas lifi yönü (derece, görüntü koordinatında; vücudun sol yarısı için — sağda aynalanır). */
    fun fiberAngle(key: String): Float = when (key) {
        "traps" -> -35f; "traps_mid" -> 0f; "infraspinatus" -> 20f
        "lats" -> -55f; "lats_front" -> -65f; "lower_back" -> 90f
        "obliques", "obliques_back" -> 62f; "abs" -> 90f
        "chest_upper" -> -25f; "chest_lower" -> 8f
        "front_delt" -> 70f; "side_delt" -> 90f; "rear_delt" -> 15f
        "biceps" -> 88f; "triceps" -> 90f; "forearm" -> 80f
        "glute_med" -> -30f; "glutes" -> -38f; "adductors" -> 105f
        "quads" -> 84f; "hamstrings" -> 92f; "tibialis", "calves" -> 92f
        else -> 90f
    }
}
